type Position = "CF" | "RF" | "LF" | "2B" | "SS" | "3B" | "1B" | "C" | "DH";
type RosterNeed = "RHP" | "CF" | "C";
type Player = readonly [string, Position, string, number, number, number];
type DecisionEntry = { id: number; time: string; area: string; title: string; note: string };

