function AccountMenu({ onClose, onOpen }: { onClose: () => void; onOpen: (overlay: OverlayId) => void }) { return <><button className="popover-scrim" type="button" aria-label="Close coach menu" onClick={onClose} /><section className="account-menu"><div><span className="initial-avatar"><img src="/assets/club/generic-player.png" alt="" /></span><span><strong>Jamie Morales</strong><small>Head Coach - 3rd season</small></span></div><button type="button" onClick={() => onOpen("coach")}><IdCardIcon />Coach profile<ChevronRightIcon /></button><button type="button" onClick={() => onOpen("settings")}><GearIcon />Settings<ChevronRightIcon /></button></section></>; }

function OverlayShell({ eyebrow, title, onClose, children, floating }: { eyebrow: string; title: string; onClose: () => void; children: React.ReactNode; floating?: React.ReactNode }) { return <section className="full-overlay"><header><button type="button" aria-label="Back" onClick={onClose}><ArrowLeftIcon /></button><div><small>{eyebrow}</small><h1>{title}</h1></div></header><MobileScroll>{children}</MobileScroll>{floating}</section>; }

function OverlayRouter({ id, selectedName, watchedPrograms, jobWatchlist, decisionLog, onToggleProgramWatch, onToggleJobWatch, onLog, onClose, onOpen, onPlayer, onTeam }: { id: Exclude<OverlayId, "account" | null>; selectedName: string; watchedPrograms: string[]; jobWatchlist: string[]; decisionLog: DecisionEntry[]; onToggleProgramWatch: (name: string) => void; onToggleJobWatch: (name: string) => void; onLog: (entry: Omit<DecisionEntry, "id" | "time">) => void; onClose: () => void; onOpen: (overlay: OverlayId) => void; onPlayer: (name?: string) => void; onTeam: (name?: string) => void }) {
  switch (id) {
    case "player": return <PlayerProfile name={selectedName} onClose={onClose} onLog={onLog} />; case "team": return <TeamProfile name={selectedName} watchedPrograms={watchedPrograms} jobWatchlist={jobWatchlist} onToggleProgramWatch={onToggleProgramWatch} onToggleJobWatch={onToggleJobWatch} onClose={onClose} onPlayer={onPlayer} onLog={onLog} />; case "coach": return <CoachProfile onClose={onClose} />; case "settings": return <SettingsOverlay onClose={onClose} onOpen={onOpen} />; case "inbox": return <InboxOverlay onClose={onClose} decisionLog={decisionLog} />; case "depth": return <DepthOverlay onClose={onClose} onPlayer={onPlayer} />; case "press": return <PressOverlay onClose={onClose} onLog={onLog} />; case "moves": return <MovesOverlay onClose={onClose} />; case "board": return <RecruitingBoard onClose={onClose} />; case "box": return <BoxScore onClose={onClose} onPlayer={onPlayer} />; case "saves": return <SavesOverlay onClose={onClose} onOpen={onOpen} />; case "career": return <CareerOverlay onClose={onClose} />; case "jobs": return <JobsOverlay onClose={onClose} onTeam={onTeam} />;
  }
}

