type DraftView = "keep" | "departing" | "board" | "undrafted";
type KeepPitchView = "role" | "development" | "opportunity" | "home";

function DraftDesk({ needFocus, onNeedFocus, onPlayer, onProspect }: { needFocus: RosterNeed | null; onNeedFocus: (need: RosterNeed | null) => void; onPlayer: (name?: string) => void; onProspect: (name?: string) => void }) {
  const [view, setView] = useState<DraftView>("keep");
  const [open, setOpen] = useState<string | null>(null);
  const [pitch, setPitch] = useState<KeepPitchView>("role");
  const [offer, setOffer] = useState(12);
  const [pitched, setPitched] = useState<string[]>([]);
  const keep = [["M. Harris", "Junior · SS · 83 OVR", "ROUND 2"], ["A. Delgado", "Junior · LF · 81 OVR", "ROUND 4"]];
  const pitches: Array<[KeepPitchView, string, string]> = [["role", "A bigger role", "Promise the everyday spot and the ball in his hands."], ["development", "Development plan", "Show him the work that turns his tools into a pro career."], ["opportunity", "Prove it here", "Sell the games, the stage, and the chance to own a program."], ["home", "Stay close", "Make the case for the people and place he already trusts."]];
  const boardRows: Array<[string, string, string]> = [["N. Calloway", "SS · 92 POT · Midwest", "TIER 1"], ["S. Bae", "RHP · 88 POT · West", "TIER 1"], ["M. Cruz", "C · 86 POT · East", "TIER 2"], ["P. Kline", "RHP · 76 POT · East", "ROUND 5"], ["J. Flores", "CF · 73 POT · Midwest", "ROUND 6"]];
  const focusedBoard = needFocus ? boardRows.filter(([, note]) => note.startsWith(`${needFocus} ·`)) : boardRows;
  const activeName = open;
  return <>
    <ModuleIntro kicker="AMATEUR DRAFT" title="Keep the right people" text="The draft takes your best players first. Pitch returning players, review departures, and work the national board." />
    <section className="metric-strip"><Metric label="YOU LOST" value="2" note="DRAFTED" /><Metric label="ON THE PHONE" value="2" note="ELIGIBLE" /><Metric label="BUDGET LEFT" value="$48" note="OF $60" /></section>
    <AcquisitionNeeds focus={needFocus} onChange={onNeedFocus} />
    <Segmented label="Draft section" value={view} onChange={setView} options={[{ value: "keep", label: "Keep" }, { value: "departing", label: "Departing" }, { value: "board", label: "Board" }, { value: "undrafted", label: "Undrafted" }]} />
    {view === "keep" && <>
      <div className="flow-section-title"><span className="label">THE PHONE CALLS</span><b>$48 RETENTION MONEY LEFT</b></div>
      <section className="retention-list">{keep.map(([name, note, round]) => <button type="button" key={name} onClick={() => setOpen(name)}><span className="portrait"><img src="/assets/club/generic-player.png" alt="" /></span><span><strong>{name}</strong><small>{note} · {round}</small></span><b>{pitched.includes(name) ? "PITCHED" : "OPEN CALL"}</b><ChevronRightIcon /></button>)}</section>
      {activeName && <section className="draft-pitch"><div className="postseason-panel-heading"><div><small>RETENTION CALL · {activeName}</small><h3>Make the case</h3></div><button type="button" onClick={() => setOpen(null)}><Cross1Icon /> Close</button></div><button className="draft-player-link" type="button" onClick={() => onPlayer(activeName)}><PersonIcon /> Open player profile</button><FieldNote title="What he wants" text="He wants a bigger role, a visible development plan, and a reason to believe this is the fastest route to his next level." /><div className="draft-pitch-options">{pitches.map(([value, label]) => <button className={pitch === value ? "active" : ""} type="button" key={value} onClick={() => setPitch(value)}><strong>{label}</strong><small>{value === pitch ? "Selected" : "Choose this pitch"}</small></button>)}</div><div className="offer-stepper"><span><small>RETENTION OFFER</small><strong>${offer}M</strong></span><button type="button" disabled={offer <= 0} onClick={() => setOffer(Math.max(0, offer - 5))}>-5</button><button type="button" onClick={() => setOffer(Math.min(48, offer + 5))}>+5</button><button type="button" onClick={() => setOffer(48)}>ALL</button></div><button className="pitch-submit" type="button" onClick={() => { setPitched((items) => items.includes(activeName) ? items : [...items, activeName]); setOpen(null); }}>MAKE THE CASE</button></section>}
    </>}
    {view === "departing" && <><FieldNote title="THE HOLES THIS LEAVES" text="Every drafted player becomes a recruiting need. These are the roster spots to refill after retention calls are done." /><ListRows onOpen={onPlayer} rows={[["R. Collins", "Senior · RHP · Draft projection R6", "LEAVING"], ["E. Rivers", "Senior · C · Graduation", "LEAVING"], ["M. Harris", "Junior · SS · Retention call open", "PENDING"]]} /></>}
    {view === "board" && <><section className="budget-bar"><span><small>NATIONAL DRAFT BOARD</small><strong>{needFocus ? `${needFocus} PRIORITY · ${focusedBoard.length} NAMES` : "ROUND 1 · 30 NAMES"}</strong></span><i><b style={{ width: "36%" }} /></i></section><ListRows onOpen={onProspect} rows={focusedBoard} /></>}
    {view === "undrafted" && <ListRows onOpen={onProspect} rows={[["I. Davis", "C · 75 POT · 2 years", "CALL"], ["J. Flores", "CF · 73 POT · 3 years", "CALL"], ["K. Young", "RHP · 71 POT · 2 years", "CALL"]]} />}
  </>;
}

type PortalView = "leaving" | "available" | "shortlist";
type PortalCandidate = { name: string; role: string; school: string; ovr: string; reason: string; fit: string; cost: string; urgency: string };

function PortalDesk({ needFocus, onNeedFocus, onPlayer }: { needFocus: RosterNeed | null; onNeedFocus: (need: RosterNeed | null) => void; onPlayer: (name?: string) => void }) {
  const [view, setView] = useState<PortalView>("leaving");
  const [contacted, setContacted] = useState<string[]>([]);
  const [shortlist, setShortlist] = useState<string[]>(["A. Scott", "P. Kline"]);
  const leaving: PortalCandidate[] = [
    { name: "T. Brooks", role: "RHP · Junior", school: "River City", ovr: "84 OVR", reason: "Wants the closer role he was promised.", fit: "CLOSER NEED", cost: "$300K", urgency: "2 DAYS LEFT" },
    { name: "J. Kim", role: "CF · Sophomore", school: "River City", ovr: "80 OVR", reason: "Playing time disappeared after the regional run.", fit: "OUTFIELD DEPTH", cost: "$260K", urgency: "4 DAYS LEFT" },
    { name: "D. Young", role: "LHP · Junior", school: "River City", ovr: "78 OVR", reason: "Family move has him looking closer to home.", fit: "LEFTY ARM", cost: "$220K", urgency: "6 DAYS LEFT" },
  ];
  const available: PortalCandidate[] = [
    { name: "A. Scott", role: "CF · Junior · 2 years", school: "From Harbor", ovr: "82 OVR", reason: "A two-way outfielder who wants a starting spot.", fit: "OUTFIELD DEPTH", cost: "$500K", urgency: "HOT FIT" },
    { name: "P. Kline", role: "RHP · Sophomore · 3 years", school: "From Metro", ovr: "79 OVR", reason: "Power arm with a late-inning pitch mix.", fit: "BULLPEN NEED", cost: "$420K", urgency: "WATCH" },
    { name: "I. Davis", role: "C · Junior · 2 years", school: "From Capitol", ovr: "77 OVR", reason: "Defensive catcher who can stabilize the room.", fit: "CATCHER DEPTH", cost: "$360K", urgency: "WATCH" },
  ];
  const current = view === "leaving" ? leaving : available.filter((candidate) => !needFocus || candidate.role.startsWith(needFocus));
  const shown = view === "shortlist" ? available.filter((candidate) => shortlist.includes(candidate.name)) : current;
  const toggleShortlist = (name: string) => setShortlist((items) => items.includes(name) ? items.filter((item) => item !== name) : [...items, name]);
  const logAction = (name: string) => setContacted((items) => items.includes(name) ? items : [...items, name]);
  return <>
    <section className="portal-command-center">
      <div className="portal-command-top"><div><small>TRANSFER PORTAL · DAY 3 OF 10</small><h1>Transfer room</h1><p>Keep the promises that matter. Spend the rest on the hole that wins next year.</p></div><div className="portal-command-mark"><EnvelopeClosedIcon /><strong>6</strong><span>DAYS OPEN</span></div></div>
      <div className="portal-budget-card"><div><small>SHARED PORTAL POOL</small><strong>$1.4M</strong><span>$900K free after current commitments</span></div><div className="portal-budget-meter"><b /></div><small>Retention calls and incoming offers draw from the same pool.</small></div>
    </section>
    <AcquisitionNeeds focus={needFocus} onChange={onNeedFocus} />
    <section className="portal-needs-strip"><div><small>ROSTER PRESSURE</small><strong>{needFocus ? `${needFocus} candidates are highlighted` : "3 decisions before recruiting"}</strong></div><div className="portal-need-tags"><span className={needFocus === "RHP" ? "critical" : ""}>RHP</span><span className={needFocus === "CF" ? "critical" : ""}>CF</span><span className={needFocus === "C" ? "critical" : ""}>C</span></div></section>
    <Segmented label="Portal mode" value={view} onChange={setView} options={[{ value: "leaving", label: "Leaving you" }, { value: "available", label: "Available" }, { value: "shortlist", label: `Shortlist ${shortlist.length}` }]} />
    <div className="portal-mode-heading"><div><small>{view === "leaving" ? "RETENTION BOARD" : view === "available" ? "INCOMING BOARD" : "YOUR SHORTLIST"}</small><h2>{view === "leaving" ? "Who needs an answer" : view === "available" ? "Who can change the roster" : "The calls worth making"}</h2></div><span>{shown.length} {shown.length === 1 ? "player" : "players"}</span></div>
    {shown.length === 0 ? <section className="portal-empty"><StarIcon /><strong>Shortlist is clear</strong><p>Star an incoming player and he will land here beside your roster pressure.</p></section> : <section className="portal-board">{shown.map((candidate) => { const isLeaving = view === "leaving"; const isContacted = contacted.includes(candidate.name); const isShortlisted = shortlist.includes(candidate.name); return <article className={`portal-candidate ${isLeaving ? "leaving" : "incoming"}`} key={candidate.name}><div className="portal-candidate-head"><button className="portal-player" type="button" onClick={() => onPlayer(candidate.name)}><span className="portal-avatar"><img src="/assets/club/generic-player.png" alt="" /></span><span><strong>{candidate.name}</strong><small>{candidate.role} · {candidate.school}</small></span></button><div className="portal-candidate-grade"><strong>{candidate.ovr}</strong><small>{candidate.fit}</small></div></div><div className="portal-candidate-story"><small>{isLeaving ? "WHY HE IS LOOKING" : "WHY HE FITS"}</small><p>{candidate.reason}</p></div><div className="portal-candidate-meta"><span><small>{isLeaving ? "ANSWER BY" : "PORTAL COST"}</small><b>{isLeaving ? candidate.urgency : candidate.cost}</b></span><span><small>{isLeaving ? "KEEPING HIM" : "WINDOW"}</small><b>{isLeaving ? candidate.cost : candidate.urgency}</b></span><button className={isShortlisted ? "starred" : ""} type="button" aria-label={`${isShortlisted ? "Remove" : "Add"} ${candidate.name} ${isLeaving ? "from" : "to"} shortlist`} onClick={() => toggleShortlist(candidate.name)}><StarIcon /></button></div><div className="portal-candidate-actions"><button type="button" onClick={() => onPlayer(candidate.name)}><PersonIcon /> Profile</button><button type="button" className={isContacted ? "done" : ""} onClick={() => logAction(candidate.name)}>{isContacted ? (isLeaving ? "CALL LOGGED" : "OFFER SENT") : isLeaving ? `CALL HIM BACK · ${candidate.cost}` : `SEND OFFER · ${candidate.cost}`}<ChevronRightIcon /></button></div></article>; })}</section>}
    <FieldNote title={view === "leaving" ? "THE DEADLINE IS THE DECISION" : view === "available" ? "THE POOL IS SHARED" : "SHORTLISTED FITS"} text={view === "leaving" ? "A player who is still waiting is not safe. Log the call, then spend enough to make the promise believable." : view === "available" ? "Every incoming offer reduces what you can use to retain your own players and recruit the class." : "Shortlist is a planning view. Nothing is signed until you send the offer on the player card."} />
  </>;
}

type RecruitingView = "recruits" | "targets" | "commits" | "needs" | "roster";
type RecruitingFilter = "all" | "in-state" | "hitters" | "pitchers";

function RecruitingDesk({ needFocus, onNeedFocus, onProspect }: { needFocus: RosterNeed | null; onNeedFocus: (need: RosterNeed | null) => void; onProspect: (name?: string) => void }) {
  const [view, setView] = useState<RecruitingView>("recruits");
  const [filterOpen, setFilterOpen] = useState(false);
  const [filter, setFilter] = useState<RecruitingFilter>("all");
  const [targets, setTargets] = useState<string[]>(["N. Calloway"]);
  const prospects = [["N. Calloway", "SS · Midwest · 92 POT", "in-state", "TIER 1"], ["S. Bae", "RHP · West · 88 POT", "pitchers", "TIER 1"], ["M. Cruz", "C · East · 86 POT", "hitters", "TIER 2"], ["J. Flores", "CF · Midwest · 82 POT", "in-state", "TIER 2"], ["K. Young", "RHP · South · 79 POT", "pitchers", "TIER 3"]];
  const filtered = prospects.filter(([, note, kind]) => (!needFocus || note.startsWith(`${needFocus} ·`)) && (filter === "all" || kind === filter)).filter(([name]) => view === "targets" ? targets.includes(name) : view === "commits" ? name === "N. Calloway" : true);
  const addTarget = (name: string) => setTargets((items) => items.includes(name) ? items : [...items, name]);
  return <>
    <ModuleIntro kicker="RECRUITING · WEEK 4 OF 6" title="The board" text="Scout, call, visit, and decide where this week's energy belongs. Every tab answers a different recruiting question." />
    <section className="metric-strip"><Metric label="SCHOLARSHIPS" value="4 / 8" note="COMMITTED" /><Metric label="BUDGET" value="$18 / 30" note="HOURS LEFT" /><Metric label="PRESTIGE" value="★★★★☆" note="PROGRAM PULL" /></section>
    <AcquisitionNeeds focus={needFocus} onChange={onNeedFocus} />
    <div className="recruiting-toolbar"><button className={filterOpen ? "active" : ""} type="button" onClick={() => setFilterOpen((open) => !open)}><MixerHorizontalIcon />{filterOpen ? "Close filter" : "Filter"}</button><span>{filter !== "all" ? `${filter} filter on` : "All prospects"}</span></div>
    {filterOpen && <section className="recruiting-filter"><div className="flow-section-title"><span className="label">FILTER THE BOARD</span><button type="button" onClick={() => setFilter("all")}>Clear</button></div><Segmented label="Recruiting filter" value={filter} onChange={setFilter} options={[{ value: "all", label: "All" }, { value: "in-state", label: "In-state" }, { value: "hitters", label: "Hitters" }, { value: "pitchers", label: "Pitchers" }]} /><FieldNote title="Why filter" text="Filters shape only the Recruits list. Targets, commits, needs, and roster stay focused on their own job." /></section>}
    <Segmented label="Recruiting section" value={view} onChange={setView} options={[{ value: "recruits", label: "Recruits" }, { value: "targets", label: `Targets ${targets.length}` }, { value: "commits", label: "Commits 1" }, { value: "needs", label: "Needs 3" }, { value: "roster", label: "Roster" }]} />
    {view === "needs" && <section className="needs-board">{[["RHP", "Need two late-inning arms", "S. Bae and P. Kline fit the board"], ["CF", "Need one everyday outfielder", "J. Flores covers the future lane"], ["C", "Need dependable depth", "M. Cruz fits the room"]].map(([pos, need, answer]) => <button type="button" key={pos} onClick={() => { onNeedFocus(pos as RosterNeed); setView("recruits"); setFilter(pos === "RHP" ? "pitchers" : pos === "CF" ? "in-state" : "hitters"); }}><strong>{pos}</strong><span><b>{need}</b><small>{answer}</small></span><ChevronRightIcon /></button>)}</section>}
    {view === "roster" && <ListRows onOpen={onProspect} rows={[["N. Calloway", "SS · Committed · 92 POT", "SIGNED"], ["S. Bae", "RHP · Target · 88 POT", "VISIT"], ["M. Cruz", "C · Prospect · 86 POT", "BOARD"]]} />}
    {view !== "needs" && view !== "roster" && <section className="prospect-list">{filtered.map(([name, note, , tier]) => <div className="recruit-row" key={name}><button type="button" onClick={() => onProspect(name)}><span><strong>{name}</strong><small>{note}</small></span><b>{tier}</b><ChevronRightIcon /></button><button type="button" onClick={() => addTarget(name)} className={targets.includes(name) ? "done" : ""}>{targets.includes(name) ? (view === "commits" ? "COMMITTED" : "TARGETED") : view === "targets" ? "SET VISIT" : "ADD TO TARGETS"}</button></div>)}</section>}
    <section className="budget-bar"><span><small>WEEKLY RECRUITING HOURS</small><strong>18 / 30</strong></span><i><b style={{ width: "60%" }} /></i></section>
  </>;
}

function SigningDesk({ onProspect }: { onProspect: (name?: string) => void }) {
  const [view, setView] = useState<"mine" | "rankings" | "all">("mine");
  const rows: Array<[string, string, string]> = view === "rankings" ? [["1. Capitol Stars", "8 commits · 4 elite", "94.2"], ["7. River City", "12 commits · 2 elite", "88.1"], ["8. Metro Kings", "10 commits · 3 elite", "87.5"]] : view === "all" ? [["N. Calloway", "SS · 92 POT · River City", "SIGNED"], ["S. Bae", "RHP · 88 POT · River City", "SIGNED"], ["M. Cruz", "C · 86 POT · Harbor", "SIGNED"], ["A. Scott", "CF · 84 POT · Capitol", "SIGNED"], ["J. Flores", "CF · 82 POT · Metro", "SIGNED"]] : [["N. Calloway", "SS · 92 POT · Elite", "SIGNED"], ["S. Bae", "RHP · 88 POT · Impact", "SIGNED"], ["M. Cruz", "C · 86 POT · Depth", "SIGNED"]];
  return <><ModuleIntro kicker="SIGNING DAY" title="The class arrives" text="Review your class, national rankings, every recruit, and the walk-ons who fill what the board could not." /><section className="metric-strip"><Metric label="SIGNED" value="3" note="YOUR CLASS" /><Metric label="CLASS POINTS" value="88.1" note="NATIONAL" /><Metric label="WALK-ONS" value="2" note="ROSTER FILL" /></section><Segmented label="Signing section" value={view} onChange={setView} options={[{ value: "mine", label: "Your class" }, { value: "rankings", label: "Rankings" }, { value: "all", label: "Every recruit" }]} /><section className="signing-class"><strong>#7</strong><span><small>NATIONAL CLASS</small><h2>River City</h2><p>2 elite · 4 impact · 6 depth</p></span></section><ListRows onOpen={view === "rankings" ? undefined : onProspect} rows={rows} />{view === "mine" && <FieldNote title="WALK-ONS REPORTING" text="Two roster spots were filled by the walk-on class. They are not counted as signed recruits." />}</>;
}

type PostseasonStage = "conference" | "regionals" | "national";
type PostseasonView = "winners" | "losers" | "your-region" | "full-field" | "final";

function PostseasonDesk({ onAdvance, onPlayer }: { onAdvance: () => void; onPlayer: (name?: string) => void }) {
  const [stage, setStage] = useState<PostseasonStage>("conference");
  const [view, setView] = useState<PostseasonView>("winners");
  const [completed, setCompleted] = useState<PostseasonStage[]>([]);
  const [simulated, setSimulated] = useState(false);
  const [lineupOpen, setLineupOpen] = useState(false);
  const [boxOpen, setBoxOpen] = useState(false);
  const [agendaOpen, setAgendaOpen] = useState(false);
  const [notice, setNotice] = useState("Your conference tournament opens the June desk.");
  const stages: Array<{ id: PostseasonStage; label: string; note: string }> = [
    { id: "conference", label: "Conference", note: "Double elimination · top four advance" },
    { id: "regionals", label: "Regionals", note: "Best of three · 16 sites" },
    { id: "national", label: "National", note: "Two brackets · championship series" },
  ];
  const stageIndex = stages.findIndex((item) => item.id === stage);
  const meta = stages[stageIndex];
  const nextStage = stages[stageIndex + 1];
  const defaultView = (next: PostseasonStage): PostseasonView => next === "regionals" ? "your-region" : "winners";

  const chooseStage = (next: PostseasonStage) => {
    if (next !== stage && !completed.includes(next)) return;
    setStage(next);
    setView(defaultView(next));
    setSimulated(false);
    setNotice(next === "conference" ? "Review the conference field and your path through it." : next === "regionals" ? "Sixteen best-of-three series decide the national field." : "Two national brackets feed the championship series.");
  };
  const advanceStage = () => {
    setSimulated(true);
    setNotice(stage === "national" ? "River City has finished the tournament. The season can now be reviewed." : `${meta.label} complete. ${nextStage?.label ?? "Awards"} are next.`);
    if (nextStage) {
      setCompleted((items) => items.includes(stage) ? items : [...items, stage]);
      setStage(nextStage.id);
      setView(defaultView(nextStage.id));
      setSimulated(false);
    } else {
      onAdvance();
    }
  };
  const simulateGame = () => {
    setSimulated(true);
    setNotice(stage === "conference" ? "River City wins its opener, 7-4. The winners path is still alive." : stage === "regionals" ? "River City takes Game 1, 5-2. One more win sends the club onward." : "River City wins the next national game, 6-3. The championship path is open.");
  };
  const viewOptions = stage === "regionals"
    ? [{ value: "your-region" as const, label: "Your region" }, { value: "full-field" as const, label: "Full field" }]
    : stage === "national"
      ? [{ value: "winners" as const, label: "Winners" }, { value: "losers" as const, label: "Losers" }, { value: "final" as const, label: "Final" }]
      : [{ value: "winners" as const, label: "Winners" }, { value: "losers" as const, label: "Losers" }];
  const nextLabel = stage === "conference" ? "Advance to regionals" : stage === "regionals" ? "Advance to nationals" : "To awards night";

  return <>
    <div className="postseason-workspace">
      <ModuleIntro kicker="JUNE 12 · POSTSEASON" title="The June desk" text="Follow the tournament from your conference bracket to the national championship, then carry the season into awards and roster decisions." />
      <section className="postseason-hero">
        <div><small>RIVER CITY ROVERS</small><strong>{stage === "conference" ? "Top four travel" : stage === "regionals" ? "One series from Omaha" : "The whole country is watching"}</strong><p>{notice}</p></div>
        <div className="postseason-hero-mark"><StarIcon /><span>{stageIndex + 1}/3</span></div>
      </section>
      <section className={`postseason-agenda${agendaOpen ? " open" : ""}`}>
        <button className="postseason-agenda-toggle" type="button" aria-expanded={agendaOpen} onClick={() => setAgendaOpen((open) => !open)}><span><small>NEXT UP · TONIGHT</small><strong>{stage === "conference" ? "Conference opener vs Harbor" : stage === "regionals" ? "Regional Game 1" : "National bracket game"}</strong></span><b>{stage === "conference" ? "2 decisions" : "1 decision"}</b><ChevronDownIcon /></button>
        {agendaOpen && <div className="postseason-agenda-list"><button type="button" onClick={() => { setView(stage === "regionals" ? "your-region" : "winners"); setNotice("The tournament path is open for review."); }}><span><small>TOMORROW</small><strong>{stage === "conference" ? "Regional draw watch" : "Travel and recovery"}</strong></span><ChevronRightIcon /></button><button type="button" onClick={() => setNotice("Roster priority logged: pursue late-inning RHP depth after the tournament.")}><span><small>JUN 15</small><strong>Log late-inning RHP priority</strong></span><ChevronRightIcon /></button></div>}
      </section>
      <section className="postseason-stage-rail" aria-label="Postseason stages">
        {stages.map((item, index) => {
          const reachable = item.id === stage || completed.includes(item.id);
          return <button className={`${item.id === stage ? "active" : ""} ${completed.includes(item.id) ? "done" : ""}`} key={item.id} type="button" disabled={!reachable} onClick={() => chooseStage(item.id)}><span>{completed.includes(item.id) ? <CheckIcon /> : index + 1}</span><b>{item.label}</b><small>{item.note}</small></button>;
        })}
      </section>
      <Segmented label="Postseason view" value={view} onChange={setView} options={viewOptions} />
      <section className="postseason-event-head"><div><small>{meta.label.toUpperCase()} EVENT</small><h2>{stage === "conference" ? "East Coast Conference" : stage === "regionals" ? "The road to Omaha" : "National championship"}</h2></div><span>{simulated ? "UPDATED" : "LIVE DESK"}</span></section>
      {stage === "conference" && <ConferenceBracket view={view === "losers" ? "losers" : "winners"} onBox={() => setBoxOpen(true)} />}
      {stage === "regionals" && <RegionalBoard view={view === "full-field" ? "full-field" : "your-region"} onBox={() => setBoxOpen(true)} />}
      {stage === "national" && <NationalBoard view={view === "losers" ? "losers" : view === "final" ? "final" : "winners"} onBox={() => setBoxOpen(true)} />}
      <section className="postseason-next-card">
        <div className="postseason-next-kicker"><small>YOUR NEXT GAME</small><span>{simulated ? "FINAL" : "GAME 1"}</span></div>
        <div className="postseason-next-match"><strong>RIV</strong><em>{simulated ? "7" : "--"}</em><span>vs</span><strong>HBR</strong><em>{simulated ? "4" : "--"}</em></div>
        <p>{stage === "conference" ? "Conference tournament opener · winners bracket" : stage === "regionals" ? "Regional series · Game 1 of 3" : "National bracket · winners side"}</p>
        <div className="postseason-action-grid"><button type="button" onClick={() => setLineupOpen((open) => !open)}><IdCardIcon />{lineupOpen ? "Close lineup" : "Set lineup"}</button><button type="button" onClick={simulateGame}><PlayIcon />Sim next game</button><button type="button" onClick={() => setBoxOpen(true)}><BarChartIcon />Open box score</button></div>
      </section>
      {lineupOpen && <section className="postseason-lineup"><div className="postseason-panel-heading"><div><small>YOUR CARD</small><h3>Postseason lineup</h3></div><button type="button" onClick={() => onPlayer("Marcus Harris")}><PersonIcon /> Player card</button></div>{lineup.slice(0, 6).map((row, index) => <button className="postseason-lineup-row" type="button" key={row[0]} onClick={() => onPlayer(row[0])}><span>{index + 1}</span><strong>{row[0]}</strong><small>{row[1]} · {row[2]} bats</small><b>{row[3]}</b><ChevronRightIcon /></button>)}</section>}
      {boxOpen && <section className="postseason-box-score"><div className="postseason-panel-heading"><div><small>FINISHED GAME</small><h3>River City 7 · Harbor 4</h3></div><button type="button" onClick={() => setBoxOpen(false)}><Cross1Icon /> Close</button></div><div className="box-score-line"><span>RIV</span><strong>7</strong><small>10 H · 1 E</small></div><div className="box-score-line"><span>HBR</span><strong>4</strong><small>8 H · 2 E</small></div><div className="box-score-foot"><span>Winning pitcher</span><b>R. Collins · 6.2 IP · 2 ER</b></div></section>}
      <button className="postseason-next" type="button" onClick={advanceStage}>{nextLabel}<ChevronRightIcon /></button>
    </div>
  </>;
}

function ConferenceBracket({ view, onBox }: { view: "winners" | "losers"; onBox: () => void }) {
  const matches = view === "winners" ? [["RIV", "7", "HBR", "4", "FINAL"], ["CAP", "5", "MET", "2", "FINAL"], ["RIV", "--", "CAP", "--", "SEMIFINAL"]] : [["HBR", "--", "LAK", "--", "ELIMINATION"], ["MET", "--", "TID", "--", "ELIMINATION"], ["LOSER SF", "--", "WINNER", "--", "CONFERENCE FINAL"]];
  return <section className="bracket-board"><div className="bracket-board-heading"><div><small>DOUBLE ELIMINATION</small><h3>{view === "winners" ? "Winners bracket" : "Losers bracket"}</h3></div><span>TOP FOUR ADVANCE</span></div><div className="bracket-grid">{matches.map(([a, as, b, bs, label]) => <button className={`${a === "RIV" || b === "RIV" ? "is-yours" : ""} bracket-match`} type="button" key={`${a}-${b}-${label}`} onClick={onBox}><small>{label}</small><span><b>{a}</b><strong>{as}</strong></span><span><b>{b}</b><strong>{bs}</strong></span></button>)}</div><p className="bracket-caption">Every conference runs its own eight-team double-elimination tournament. Tap a game to inspect its line.</p></section>;
}

function RegionalBoard({ view, onBox }: { view: "your-region" | "full-field"; onBox: () => void }) {
  const series = view === "your-region" ? [["RIV", "HBR", "1-0", "Game 2 tomorrow"], ["CAP", "MET", "0-0", "Not started"], ["RIV", "CAP", "--", "Regional final"]] : [["RIV", "HBR", "1-0", "River City leads"], ["CAP", "MET", "0-0", "Not started"], ["LON", "TID", "1-1", "Deciding game"], ["CST", "WES", "2-0", "Crestview advances"], ["NAT", "VAL", "2-1", "Valley advances"]];
  return <section className="bracket-board"><div className="bracket-board-heading"><div><small>BEST OF THREE SERIES</small><h3>{view === "your-region" ? "Great Lakes regional" : "Sixteen-site field"}</h3></div><span>{view === "your-region" ? "YOUR PATH" : "ALL REGIONS"}</span></div><div className="series-list">{series.map(([a, b, score, status]) => <button className={`${a === "RIV" || b === "RIV" ? "is-yours" : ""} series-match`} type="button" key={`${a}-${b}-${score}`} onClick={onBox}><span><small>{status}</small><b>{a}</b><strong>{score}</strong><b>{b}</b></span><ChevronRightIcon /></button>)}</div><p className="bracket-caption">Sixteen best-of-three regional series decide the twenty-team national field.</p></section>;
}

function NationalBoard({ view, onBox }: { view: "winners" | "losers" | "final"; onBox: () => void }) {
  if (view === "final") return <section className="bracket-board"><div className="bracket-board-heading"><div><small>CHAMPIONSHIP SERIES</small><h3>The final</h3></div><span>BEST OF 3</span></div><div className="final-scoreboard"><div><small>BRACKET A</small><strong>RIV</strong><b>--</b></div><span>VS</span><div><small>BRACKET B</small><strong>CAP</strong><b>--</b></div></div><button className="final-game-link" type="button" onClick={onBox}><BarChartIcon /> Open championship box score <ChevronRightIcon /></button><p className="bracket-caption">The two bracket champions meet here. The winner is the national champion.</p></section>;
  const games = view === "winners" ? [["RIV", "6", "TEX", "3", "WINNERS A"], ["CAP", "4", "PAC", "2", "WINNERS B"], ["RIV", "--", "CAP", "--", "CHAMPIONSHIP PATH"]] : [["HBR", "--", "LON", "--", "LOSERS A"], ["MET", "--", "WES", "--", "LOSERS B"], ["LOSER A", "--", "LOSER B", "--", "LAST CHANCE"]];
  return <section className="bracket-board"><div className="bracket-board-heading"><div><small>TWO DOUBLE-ELIMINATION BRACKETS</small><h3>{view === "winners" ? "Winners side" : "Losers side"}</h3></div><span>OMAHA NEXT</span></div><div className="bracket-grid national-grid">{games.map(([a, as, b, bs, label]) => <button className={`${a === "RIV" || b === "RIV" ? "is-yours" : ""} bracket-match`} type="button" key={`${a}-${b}-${label}`} onClick={onBox}><small>{label}</small><span><b>{a}</b><strong>{as}</strong></span><span><b>{b}</b><strong>{bs}</strong></span></button>)}</div><div className="championship-tease"><small>NATIONAL FINAL · BEST OF 3</small><strong>Bracket A champion <span>vs</span> Bracket B champion</strong><p>The two bracket winners meet for the title.</p></div></section>;
}

function Capacity() { return <section className="club-capacity"><div><small>BENCH</small><strong>5 <em>/5</em></strong><p><DotFilledIcon /><DotFilledIcon /><DotFilledIcon /><DotFilledIcon /><DotFilledIcon /></p></div><div><small>BULLPEN</small><strong>8 <em>/8</em></strong><p><DotFilledIcon /><DotFilledIcon /><DotFilledIcon /><DotFilledIcon /><DotFilledIcon /><DotFilledIcon /></p></div><div><small>ROSTER</small><strong>26 <em>/26</em></strong><p><DotFilledIcon /><DotFilledIcon /><DotFilledIcon /><DotFilledIcon /><DotFilledIcon /></p></div></section>; }
function FieldNote({ title, text }: { title: string; text: string }) { return <section className="field-note"><SewingPinIcon /><div><strong>{title}</strong><p>{text}</p></div></section>; }
